constants/settlement.js:223-228 defines the scheme and nothing consumes it:
  /** `TD/STL/26-27/000123`. The `Counter` pattern, same as invoices. */
  const SETTLEMENT_NUMBER = Object.freeze({ PREFIX: "TD/STL", PAD: 6, COUNTER_KEY: "settlementNumber" });

